-- Independent VA Alliance core schema
create extension if not exists pgcrypto with schema extensions;
create table public.directory_vas(id uuid primary key default gen_random_uuid(),name text not null unique,kind text not null check(kind in('VA','VO')),ceo_ifc_username text,website_url text,logo_url text,discord_url text,routes text[] not null default '{}',active_pilots int not null default 0 check(active_pilots>=0),total_pilots int not null default 0 check(total_pilots>=0),description text,founded_at date,created_at timestamptz default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,ifc_username text not null unique,role text not null check(role in('admin','reviewer','ceo')),va_id uuid references public.directory_vas(id) on delete set null,display_name text,created_at timestamptz default now());
create table public.applications(id uuid primary key default gen_random_uuid(),name text not null,kind text not null check(kind in('VA','VO')),ceo_ifc_username text not null,email text not null,experience text not null,operations_plan text not null,website_url text not null,website_valid boolean default false,notes text,status text not null default 'waiting' check(status in('waiting','being_reviewed')),reservation_code text unique,created_at timestamptz default now());
create table public.application_archive(id uuid primary key,name text not null,kind text not null,ceo_ifc_username text not null,email text not null,status text not null check(status in('approved','rejected')),decision_notes text,submitted_at timestamptz not null,decided_at timestamptz default now());
create table public.application_assignments(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.applications(id) on delete cascade,reviewer_id uuid not null references public.profiles(id) on delete cascade,assigned_by uuid references public.profiles(id),created_at timestamptz default now(),unique(application_id,reviewer_id));
create table public.application_reviews(id uuid primary key default gen_random_uuid(),application_id uuid not null references public.applications(id) on delete cascade,reviewer_id uuid not null references public.profiles(id) on delete cascade,verdict text not null check(verdict in('recommend','changes','decline')),review_text text not null,created_at timestamptz default now(),unique(application_id,reviewer_id));
create table public.staff_members(id uuid primary key default gen_random_uuid(),va_id uuid not null references public.directory_vas(id) on delete cascade,name text not null,ifc_username text,role_title text not null,department text,avatar_url text,active boolean default true,created_at timestamptz default now());
create table public.community_events(id uuid primary key default gen_random_uuid(),va_id uuid references public.directory_vas(id) on delete set null,title text not null,description text,starts_at timestamptz not null,ends_at timestamptz,location text,registration_url text,created_by uuid references public.profiles(id),created_at timestamptz default now());
create table public.support_requests(id uuid primary key default gen_random_uuid(),va_name text not null,contact_ifc_username text not null,contact_email text not null,help_types text[] default '{}',details text not null,status text not null default 'open' check(status in('open','in_progress','resolved')),created_at timestamptz default now());
create table public.registration_codes(id uuid primary key default gen_random_uuid(),code_hash text not null unique,role text not null check(role in('reviewer','ceo')),ifc_username text not null,va_id uuid references public.directory_vas(id) on delete cascade,expires_at timestamptz default now()+interval '7 days',used_at timestamptz,created_by uuid references public.profiles(id),created_at timestamptz default now(),check((role='ceo' and va_id is not null) or(role='reviewer' and va_id is null)));
create index applications_status_created_idx on public.applications(status,created_at desc);
create index staff_va_active_idx on public.staff_members(va_id,active);
create index events_start_idx on public.community_events(starts_at);
create or replace function public.current_role() returns text language sql stable security definer set search_path=public as $$select role from public.profiles where id=auth.uid()$$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select coalesce(public.current_role()='admin',false)$$;
create or replace function public.submit_application(p_name text,p_kind text,p_ceo_ifc_username text,p_email text,p_experience text,p_operations_plan text,p_website_url text,p_website_valid boolean,p_notes text,p_human_check boolean) returns uuid language plpgsql security definer set search_path=public as $$declare new_id uuid;begin if not coalesce(p_human_check,false) then raise exception 'Human check failed';end if;if length(trim(p_name))<2 or length(trim(p_ceo_ifc_username))<2 then raise exception 'Complete required fields';end if;if p_kind not in('VA','VO') then raise exception 'Invalid organisation type';end if;if p_website_url !~* '^https?://' or not coalesce(p_website_valid,false) then raise exception 'Verify a valid website URL first';end if;insert into public.applications(name,kind,ceo_ifc_username,email,experience,operations_plan,website_url,website_valid,notes) values(trim(p_name),p_kind,trim(p_ceo_ifc_username),trim(p_email),trim(p_experience),trim(p_operations_plan),trim(p_website_url),true,nullif(trim(p_notes),'')) returning id into new_id;return new_id;end$$;
create or replace function public.lookup_reservation(p_code text) returns table(application_id uuid,organisation_name text,organisation_type text,ceo_ifc_username text,status text,submitted_at timestamptz) language sql security definer set search_path=public as $$select a.id,a.name,a.kind,a.ceo_ifc_username,a.status,a.created_at from public.applications a where a.reservation_code=upper(trim(p_code)) and a.status='being_reviewed' limit 1$$;
create or replace function public.set_application_status(p_application_id uuid,p_status text,p_decision_notes text default null) returns text language plpgsql security definer set search_path=public as $$declare a public.applications%rowtype;code text;begin if not public.is_admin() then raise exception 'Administrator access required';end if;if p_status not in('being_reviewed','approved','rejected') then raise exception 'Invalid status';end if;select * into a from public.applications where id=p_application_id for update;if not found then raise exception 'Application not found';end if;if p_status='being_reviewed' then code:=coalesce(a.reservation_code,lpad((floor(random()*100000)::int)::text,5,'0'));update public.applications set status='being_reviewed',reservation_code=code where id=p_application_id;return code;elsif p_status='approved' then insert into public.directory_vas(name,kind,ceo_ifc_username,website_url,description) values(a.name,a.kind,a.ceo_ifc_username,a.website_url,a.operations_plan) on conflict(name) do update set ceo_ifc_username=excluded.ceo_ifc_username,website_url=excluded.website_url;insert into public.application_archive(id,name,kind,ceo_ifc_username,email,status,decision_notes,submitted_at) values(a.id,a.name,a.kind,a.ceo_ifc_username,a.email,'approved',p_decision_notes,a.created_at);delete from public.applications where id=p_application_id;return 'APPROVED';else insert into public.application_archive(id,name,kind,ceo_ifc_username,email,status,decision_notes,submitted_at) values(a.id,a.name,a.kind,a.ceo_ifc_username,a.email,'rejected',p_decision_notes,a.created_at);delete from public.applications where id=p_application_id;return 'REJECTED';end if;end$$;
create or replace function public.create_registration_invite(p_role text,p_ifc_username text,p_va_id uuid default null) returns text language plpgsql security definer set search_path=public,extensions as $$declare raw_code text;begin if not public.is_admin() then raise exception 'Administrator access required';end if;if p_role not in('ceo','reviewer') then raise exception 'Invalid role';end if;if p_role='ceo' and p_va_id is null then raise exception 'Choose a VA';end if;if p_role='reviewer' then p_va_id:=null;end if;raw_code:=upper(encode(extensions.gen_random_bytes(4),'hex'));insert into public.registration_codes(code_hash,role,ifc_username,va_id,created_by) values(encode(extensions.digest(raw_code,'sha256'),'hex'),p_role,trim(p_ifc_username),p_va_id,auth.uid());return raw_code;end$$;
create or replace function public.complete_registration(p_code text) returns jsonb language plpgsql security definer set search_path=public,extensions as $$declare inv public.registration_codes%rowtype;begin if auth.uid() is null then raise exception 'Sign in first';end if;select * into inv from public.registration_codes where code_hash=encode(extensions.digest(upper(trim(p_code)),'sha256'),'hex') and used_at is null and expires_at>now() for update;if not found then raise exception 'Code invalid, expired or already used';end if;if exists(select 1 from public.profiles where id=auth.uid()) then raise exception 'Account already registered';end if;insert into public.profiles(id,ifc_username,role,va_id) values(auth.uid(),inv.ifc_username,inv.role,inv.va_id);update public.registration_codes set used_at=now() where id=inv.id;return jsonb_build_object('role',inv.role,'va_id',inv.va_id,'ifc_username',inv.ifc_username);end$$;
create or replace function public.assign_reviewer(p_application_id uuid,p_reviewer_id uuid) returns void language plpgsql security definer set search_path=public as $$begin if not public.is_admin() then raise exception 'Administrator access required';end if;if not exists(select 1 from public.profiles where id=p_reviewer_id and role='reviewer') then raise exception 'Reviewer not found';end if;insert into public.application_assignments(application_id,reviewer_id,assigned_by) values(p_application_id,p_reviewer_id,auth.uid()) on conflict(application_id,reviewer_id) do nothing;end$$;
create or replace function public.submit_application_review(p_application_id uuid,p_verdict text,p_review_text text) returns void language plpgsql security definer set search_path=public as $$begin if public.current_role()<>'reviewer' then raise exception 'Reviewer access required';end if;if not exists(select 1 from public.application_assignments where application_id=p_application_id and reviewer_id=auth.uid()) then raise exception 'Not assigned to you';end if;insert into public.application_reviews(application_id,reviewer_id,verdict,review_text) values(p_application_id,p_verdict,p_review_text) on conflict(application_id,reviewer_id) do update set verdict=excluded.verdict,review_text=excluded.review_text,created_at=now();end$$;
create or replace function public.admin_update_va(p_va_id uuid,p_name text,p_kind text,p_ceo text,p_website text,p_logo text,p_discord text,p_routes text[],p_active int,p_total int,p_description text) returns void language plpgsql security definer set search_path=public as $$begin if not public.is_admin() then raise exception 'Administrator access required';end if;update public.directory_vas set name=p_name,kind=p_kind,ceo_ifc_username=p_ceo,website_url=p_website,logo_url=p_logo,discord_url=p_discord,routes=coalesce(p_routes,'{}'),active_pilots=greatest(p_active,0),total_pilots=greatest(p_total,0),description=p_description where id=p_va_id;end$$;
create or replace function public.ceo_update_va(p_name text,p_website text,p_logo text,p_discord text,p_routes text[],p_description text) returns void language plpgsql security definer set search_path=public as $$declare v_id uuid;begin if public.current_role()<>'ceo' then raise exception 'CEO access required';end if;select va_id into v_id from public.profiles where id=auth.uid();update public.directory_vas set name=p_name,website_url=p_website,logo_url=p_logo,discord_url=p_discord,routes=coalesce(p_routes,'{}'),description=p_description where id=v_id;end$$;
alter table public.directory_vas enable row level security;alter table public.profiles enable row level security;alter table public.applications enable row level security;alter table public.application_archive enable row level security;alter table public.application_assignments enable row level security;alter table public.application_reviews enable row level security;alter table public.staff_members enable row level security;alter table public.community_events enable row level security;alter table public.support_requests enable row level security;alter table public.registration_codes enable row level security;
create policy "Public VA directory" on public.directory_vas for select to anon,authenticated using(true);
create policy "Admin manage VAs" on public.directory_vas for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "Own profile" on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());
create policy "Admin profiles" on public.profiles for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "Active staff directory" on public.staff_members for select to anon,authenticated using(active=true or public.is_admin());
create policy "Admin staff management" on public.staff_members for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "Public events" on public.community_events for select to anon,authenticated using(true);
create policy "CEO create events" on public.community_events for insert to authenticated with check(public.current_role()='ceo' and va_id=(select va_id from public.profiles where id=auth.uid()));
create policy "CEO edit own events" on public.community_events for update to authenticated using(public.current_role()='ceo' and va_id=(select va_id from public.profiles where id=auth.uid())) with check(public.current_role()='ceo' and va_id=(select va_id from public.profiles where id=auth.uid()));
create policy "Admin event management" on public.community_events for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "Assigned application read" on public.applications for select to authenticated using(public.is_admin() or exists(select 1 from public.application_assignments aa where aa.application_id=id and aa.reviewer_id=auth.uid()));
create policy "Assignment read" on public.application_assignments for select to authenticated using(public.is_admin() or reviewer_id=auth.uid());
create policy "Admin assignment management" on public.application_assignments for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "Own review read" on public.application_reviews for select to authenticated using(public.is_admin() or reviewer_id=auth.uid());
create policy "Admin archive read" on public.application_archive for select to authenticated using(public.is_admin());
create policy "Public support submit" on public.support_requests for insert to anon,authenticated with check(true);
create policy "Admin support management" on public.support_requests for all to authenticated using(public.is_admin()) with check(public.is_admin());
grant usage on schema public to anon,authenticated;
grant select on public.directory_vas,public.staff_members,public.community_events to anon,authenticated;
grant select,insert,update,delete on public.profiles,public.applications,public.application_archive,public.application_assignments,public.application_reviews,public.staff_members,public.directory_vas,public.community_events,public.support_requests,public.registration_codes to authenticated;
grant insert on public.support_requests to anon;
grant execute on function public.submit_application(text,text,text,text,text,text,text,boolean,text,boolean),public.lookup_reservation(text) to anon,authenticated;
grant execute on function public.current_role(),public.is_admin(),public.set_application_status(uuid,text,text),public.create_registration_invite(text,text,uuid),public.complete_registration(text),public.assign_reviewer(uuid,uuid),public.submit_application_review(uuid,text,text),public.admin_update_va(uuid,text,text,text,text,text,text,text[],int,int,text),public.ceo_update_va(text,text,text,text,text[],text) to authenticated;